    padding: 14px 0; font-size: 1.1rem; font-weight: 500;
    color: var(--text-primary); border-bottom: 1px solid var(--border-color);
  }
  .hero-content { flex-direction: column; text-align: center; }
  .hero-visual { flex: none; width: 100%; max-width: 400px; height: 240px; }
  .hero-text p { margin: 0 auto 24px; }
  .hero-stats { justify-content: center; }
  .hero-pricing { justify-content: center; }
  .section { padding: 60px 0; }
  .section-title { font-size: 1.6rem; }
  .masonry { columns: 2; }
  .footer-grid { grid-template-columns: 1fr; }
  .footer-col .footer-links { display: none; }
  .footer-col.accordion-open .footer-links { display: block; }
  .footer-col h4 { cursor: pointer; display: flex; justify-content: space-between; align-items: center; padding: 12px 0; border-bottom: 1px solid var(--border-color); }
  .footer-col h4::after { content: '+'; font-size: 1.2rem; color: var(--text-muted); }
  .footer-col.accordion-open h4::after { content: '-'; }
  .sidebar { display: none; }
  .sidebar.open { display: block; position: fixed; inset: 0; z-index: 80; background: var(--bg-dark); padding: 24px; overflow-y: auto; }
  .course-grid { grid-template-columns: repeat(auto-fill, minmax(200px, 1fr)); }
  .plus-hero h1 { font-size: 2rem; }
  .pricing-card { padding: 28px 20px; }
  .pricing-card .price { font-size: 2.5rem; }
}

@media (max-width: 480px) {
  .masonry { columns: 1; }
  .course-grid { grid-template-columns: 1fr; }
  .hero-text h1 { font-size: 1.8rem; }
  .value-grid { grid-template-columns: 1fr; }
  .benefits-grid { grid-template-columns: 1fr; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: 0.01ms !important; transition-duration: 0.01ms !important; }
  .carousel-track { transition: none; }
}
